/* * @lc app=leetcode id=1302 lang=kotlin * * [1302] Deepest Leaves Sum */ class Solution { fun deepestLeavesSum(root: TreeNode?): Int = root?.let { r -> ArrayDeque<TreeNode>().apply { add(r) }.let { q -> generateSequence { if (q.isNotEmpty()) q.size else null }.map { size -> (0 until size).sumOf { _ -> q.removeFirst().let { node -> (node.left?.also { q.add(it) } ?: node).run { node.right?.also { q.add(it) }.run{node.`val`} } } } }.last() } } ?: 0 }